   516→  const referenced = new Set<string>();
   517→
   518→  const allItems = [...tasks, ...items];
   519→
   520→  // Fields that contain references
   521→  const refFields = [
   522→    "depends_on",
   523→    "blocked_by",
   524→    "implements",
   525→    "relates_to",
   526→    "tests",
   527→    "supersedes",
   528→    "spec_ref",
   529→    "context",
   530→  ];
