/**
 * Check AC "then" clauses reference actual schema fields
 * AC: @my-spec ac-N
 */
function checkACSchemaReferences(
  items: LoadedSpecItem[],
  schemaContext?: Record<string, string[]>  // Map of item types to valid fields
): CompletenessWarning[] {
  const warnings: CompletenessWarning[] = [];

  for (const item of items) {
    if (!item.acceptance_criteria || item.acceptance_criteria.length === 0) {
      continue;
    }

    const itemRef = item.slugs?.[0] 
      ? `@${item.slugs[0]}` 
      : `@${item._ulid.slice(0, 8)}`;

    for (const ac of item.acceptance_criteria) {
      // Extract schema field references from ac.then
      const fieldRefs = extractSchemaFields(ac.then);

      for (const fieldRef of fieldRefs) {
        // Validate field exists in schema for item type
        if (!isValidSchemaField(fieldRef, item.type)) {
          warnings.push({
            type: "missing_acceptance_criteria",  // or new type
            itemRef,
            itemTitle: item.title,
            message: `AC ${ac.id} references non-existent field "${fieldRef}"`,
            details: `In spec ${itemRef}: ${ac.then}`,
          });
        }
      }
    }
  }

  return warnings;
}
```

Key patterns:
- Iterate through items
- Check AC array existence
- Build itemRef from slugs or short ULID
- Process each AC, extract references from `then` clause
- Validate against schema
- Push `CompletenessWarning` objects to warnings array
- Return warnings array
- Include AC annotation in comment with spec reference

