  const dotPattern = /\b(item|spec|task|status|spec_ref|task_ref|meta_ref|plan_ref)\.(\w+)/gi;
  let match: RegExpExecArray | null;
  while ((match = dotPattern.exec(text)) !== null) {
    const field = match[2].toLowerCase();
